// --- CONFIGURACIÓN ---
const TIMEZONE = 'America/New_York';
const DEFAULT_MIN_SLOT_MINUTES = 90;
const DAYS_PER_WEEK_BLOCK = 7; // tamaño de cada bloque "semana" de opciones

// Horas en decimal (ej. 19.5 = 7:30pm). lastStart = última hora de inicio permitida
// (tope duro de "última cita", independiente de la duración del servicio).
const day = (start, end, lastStart) => ({ start, end, lastStart });

// Horario por defecto del spa. Aplica a Alejandro, Bryan, Laura, María Alejandra,
// y a CUALQUIER profesional no listado explícitamente en SPECIAL_SCHEDULES
// (Valeria, Emily, Danny, y cualquiera que se agregue a futuro).
const STANDARD = {
  1: day(8, 20, 18.5), 2: day(8, 20, 18.5), 3: day(8, 20, 18.5), 4: day(8, 20, 18.5), 5: day(8, 20, 18.5), // Lun-Vie 8am-8pm
  6: day(8, 18, 16.5), 0: day(8, 18, 16.5), // Sáb-Dom 8am-6pm
};

const EIMY_SCHEDULE = {
  2: day(15.5, 21, 19.5), 4: day(15.5, 21, 19.5), // Martes y Jueves
  3: day(17.5, 21, 19.5), 5: day(17.5, 21, 19.5), // Miércoles y Viernes
  6: day(8, 18, 16.5), 0: day(8, 18, 16.5), 1: day(8, 21, 19.5), // Sáb, Dom, Lun
};

const ASTRID_SCHEDULE = {
  6: day(16.5, 18, 16.5), // Solo sábado
};

const MATHIAS_SCHEDULE = {
  0: day(15.5, 18, 16.5), 1: day(15.5, 21, 19.5), 2: day(15.5, 21, 19.5), 3: day(15.5, 21, 19.5),
  4: day(15.5, 21, 19.5), 5: day(15.5, 21, 19.5), 6: day(15.5, 18, 16.5), // L-D
};

// Solo los profesionales con horario DISTINTO al default necesitan entrada acá.
// Cualquier nombre que no matchee ninguna clave cae en STANDARD automáticamente.
const SPECIAL_SCHEDULES = {
  eimy: EIMY_SCHEDULE,
  astrid: ASTRID_SCHEDULE,
  mathias: MATHIAS_SCHEDULE,
};

// =============================
// RESOLVER HORARIO DEL PROFESIONAL
// =============================

const profetionalNameRaw = $('When Executed by Another Workflow').item.json.ProfetionalName || '';
const profetionalNameLower = profetionalNameRaw.toLowerCase();

const specialKey = Object.keys(SPECIAL_SCHEDULES).find(key => profetionalNameLower.includes(key));
const SCHEDULE = specialKey ? SPECIAL_SCHEDULES[specialKey] : STANDARD;
const WORK_DAYS = Object.keys(SCHEDULE).map(Number);

// =============================
// OBTENER EVENTO A REPROGRAMAR
// =============================

const eventToReschedule = $node["Get an event"].json;
const eventIdToIgnore = eventToReschedule.id;

const getEventDurationMinutes = (event) => {
  if (!event?.start?.dateTime || !event?.end?.dateTime) {
    return DEFAULT_MIN_SLOT_MINUTES;
  }
  const start = new Date(event.start.dateTime);
  const end = new Date(event.end.dateTime);
  return Math.round((end - start) / 60000);
};

const REQUIRED_SLOT_MINUTES = getEventDurationMinutes(eventToReschedule);

// =============================
// OBTENER Y PREPARAR EVENTOS
// =============================

const allEvents = $input.all().map(item => item.json);

let eventsInput;
if (eventToReschedule && eventToReschedule.summary !== "Not available") {
  eventsInput = allEvents.filter(e => e.id !== eventIdToIgnore);
} else {
  eventsInput = allEvents;
}

// =============================
// HELPERS
// =============================

const nyFormatter = new Intl.DateTimeFormat('en-CA', {
  timeZone: TIMEZONE,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
});

const getMins = (date) => {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TIMEZONE,
    hour: 'numeric',
    minute: 'numeric',
    hour12: false
  }).formatToParts(date);

  let h = parseInt(parts.find(p => p.type === 'hour').value);
  if (h === 24) h = 0;

  const m = parseInt(parts.find(p => p.type === 'minute').value);
  return (h * 60) + m;
};

const minsToTime = (mins) => {
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  const ampm = h >= 12 ? 'PM' : 'AM';
  const h12 = h % 12 || 12;
  return `${h12}:${String(m).padStart(2, '0')} ${ampm}`;
};

const MONTHS_ES = [
  'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
  'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'
];

const DAYS_ES = [
  'Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'
];

// dow = día de la semana (0=Dom ... 6=Sáb), ya calculado en el loop principal
const formatSpanishDate = (dateString, dow) => {
  const [year, month, day] = dateString.split('-').map(Number);
  return `${DAYS_ES[dow]} ${day} de ${MONTHS_ES[month - 1]}`;
};

// =============================
// CALCULAR FECHA DE INICIO
// =============================

const todayNYString = nyFormatter.format(new Date());

// Fecha de la cita a reagendar (en timezone NY)
let eventDateNY = null;
if (eventToReschedule?.start?.dateTime) {
  eventDateNY = nyFormatter.format(new Date(eventToReschedule.start.dateTime));
}

// startDate = el día DESPUÉS de la cita a reagendar (o mañana si no hay fecha)
// Esto evita que se ofrezca el mismo día de la cita como opción
const referenceDate = eventDateNY && eventDateNY > todayNYString ? eventDateNY : todayNYString;
const startDate = new Date(`${referenceDate}T00:00:00`);
startDate.setDate(startDate.getDate() + 1);

const endDate = new Date(startDate);
endDate.setDate(startDate.getDate() + 30);

// =============================
// CALCULAR DISPONIBILIDAD (AGRUPADA POR SEMANA)
// =============================
// weeks[0] = bloque de los primeros 7 días desde startDate (semana 1)
// weeks[1] = los siguientes 7 días (semana 2), etc.

const weeks = [];
let currentLoopDate = new Date(startDate);
let dayIndex = 0;

while (currentLoopDate <= endDate) {
  const loopDateNY = nyFormatter.format(currentLoopDate);
  const dayOfWeek = new Date(loopDateNY + 'T00:00:00').getDay();

  const weekIndex = Math.floor(dayIndex / DAYS_PER_WEEK_BLOCK);
  if (!weeks[weekIndex]) weeks[weekIndex] = [];

  if (WORK_DAYS.includes(dayOfWeek)) {
    const currentDateString = loopDateNY;

    const daySchedule = SCHEDULE[dayOfWeek];
    const dayStartMins = daySchedule.start * 60;
    // "Última cita" = tope duro de inicio. El cierre efectivo del día para ARMAR
    // slots es el menor entre el cierre real y (última cita + duración de ESTA
    // cita). Así, start+duración<=dayEndMins ya implica start<=última cita,
    // sin agregar ningún campo nuevo a la validación existente.
    const dayEndMins = Math.min(daySchedule.end * 60, daySchedule.lastStart * 60 + REQUIRED_SLOT_MINUTES);

    const daysEvents = eventsInput.filter(e => {
      if (!e.start || !e.start.dateTime) return false;
      const evtDate = new Date(e.start.dateTime);
      const evtDateNY = nyFormatter.format(evtDate);
      return evtDateNY === currentDateString;
    });

    let slots = [{ start: dayStartMins, end: dayEndMins }];

    daysEvents.forEach(evt => {
      const evtStart = new Date(evt.start.dateTime);
      const evtEnd = new Date(evt.end.dateTime);

      const eStartMins = getMins(evtStart);
      const eEndMins = getMins(evtEnd);

      let newSlots = [];
      slots.forEach(slot => {
        if (eEndMins <= slot.start || eStartMins >= slot.end) {
          newSlots.push(slot);
        } else {
          if (slot.start < eStartMins) newSlots.push({ start: slot.start, end: eStartMins });
          if (slot.end > eEndMins) newSlots.push({ start: eEndMins, end: slot.end });
        }
      });
      slots = newSlots;
    });

    const validSlots = slots
      .filter(s => (s.end - s.start) >= REQUIRED_SLOT_MINUTES)
      .sort((a, b) => a.start - b.start);

    validSlots.forEach(slot => {
      weeks[weekIndex].push(
        // Formato: "Sábado 22 de Agosto de 9:00 AM a 6:00 PM"
        `${formatSpanishDate(currentDateString, dayOfWeek)} de ${minsToTime(slot.start)} a ${minsToTime(slot.end)}`
      );
    });
  }

  currentLoopDate.setDate(currentLoopDate.getDate() + 1);
  dayIndex++;
}

// =============================
// FORMATO FINAL — UNA LISTA POR SEMANA
// =============================
// Cada item de salida es una semana distinta, numerada desde 1 dentro de esa semana.
// Se omiten las semanas sin ningún hueco disponible.

return weeks
  .map((weekLines, i) => {
    const formatted = weekLines
      .map((line, index) => `${index + 1}. ${line}`)
      .join('\n');

    return {
      json: {
        week: i + 1,
        text: formatted
      }
    };
  })
  .filter(item => item.json.text.length > 0);
